def remplir_agence(apps, schema_editor):
    """Programmations existantes : agence actuelle de l'employé."""
    from django.utils import timezone
    Prog = apps.get_model('api', 'ProgrammationEquipe')
    UserAgence = apps.get_model('api', 'UserAgence')
    maintenant = timezone.now()
    for prog in Prog.objects.filter(agence__isnull=True):
        lignes = list(UserAgence.objects.filter(user_id=prog.user_id))
        if not lignes:
            continue
        actives = [l for l in lignes if l.date_debut <= maintenant and (l.date_fin is None or l.date_fin >= maintenant)]
        ligne = max(actives or lignes, key=lambda l: l.date_debut)
        prog.agence_id = ligne.agence_id
        prog.save(update_fields=['agence'])


